package com.voicetxt.reader;

import android.app.*;import android.os.Bundle;import android.graphics.Color;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.text.*;import android.view.*;import android.view.inputmethod.InputMethodManager;import android.content.Context;import android.widget.*;import java.util.*;

/** Lazy two-column speaker browser; selection never starts a preview. */
final class PackageSpeakerPicker extends Dialog {
    interface Host {int selected();boolean previewing(int speaker);void select(int speaker);void preview(int speaker);void stop();}
    final Activity activity;final VoiceModel pack;final Host host;final int red=0xffdf382c,ink=0xff292b30,gray=0xff85858b;
    GridView grid;EditText search;BaseAdapter adapter;final List<Integer> filtered=new ArrayList<>();
    PackageSpeakerPicker(Activity activity,VoiceModel pack,Host host){super(activity);this.activity=activity;this.pack=pack;this.host=host;}
    int dp(float n){return Math.round(n*activity.getResources().getDisplayMetrics().density);}
    GradientDrawable shape(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
    TextView text(String value,int size,int color){TextView t=new TextView(activity);t.setText(value);t.setTextSize(size);t.setTextColor(color);t.setGravity(Gravity.CENTER_VERTICAL);return t;}
    @Override protected void onCreate(Bundle state){super.onCreate(state);LinearLayout root=new LinearLayout(activity);root.setOrientation(1);GradientDrawable bg=shape(Color.WHITE,0);bg.setCornerRadii(new float[]{dp(24),dp(24),dp(24),dp(24),0,0,0,0});root.setBackground(bg);root.setPadding(dp(20),dp(12),dp(20),dp(12));setContentView(root);root.setOnApplyWindowInsetsListener((v,insets)->{v.setPadding(dp(20)+insets.getSystemWindowInsetLeft(),dp(12),dp(20)+insets.getSystemWindowInsetRight(),dp(12)+insets.getSystemWindowInsetBottom());return insets;});
        View handle=new View(activity);handle.setBackground(shape(0xffdedee2,3));LinearLayout.LayoutParams grip=new LinearLayout.LayoutParams(dp(34),dp(4));grip.gravity=Gravity.CENTER_HORIZONTAL;root.addView(handle,grip);
        LinearLayout heading=new LinearLayout(activity);heading.setGravity(Gravity.CENTER_VERTICAL);root.addView(heading);TextView title=text(pack.name,20,ink);title.setTypeface(null,Typeface.BOLD);title.setMaxLines(2);title.setEllipsize(TextUtils.TruncateAt.END);heading.addView(title,new LinearLayout.LayoutParams(0,dp(70),1));TextView close=text("×",27,gray);close.setGravity(Gravity.CENTER);close.setContentDescription(activity.getString(R.string.ui_11));heading.addView(close,new LinearLayout.LayoutParams(dp(44),dp(48)));close.setOnClickListener(v->dismiss());
        TextView hint=text(activity.getString(R.string.vp_speaker_hint,pack.speakers),12,gray);hint.setPadding(0,0,0,dp(14));root.addView(hint);
        search=new EditText(activity);search.setSingleLine(true);search.setTextSize(14);search.setTextColor(ink);search.setHintTextColor(gray);search.setHint(R.string.vp_search_speaker);search.setPadding(dp(16),0,dp(16),0);search.setBackground(shape(0xfff4f5f7,14));root.addView(search,new LinearLayout.LayoutParams(-1,dp(46)));
        TextView empty=text(activity.getString(R.string.vp_no_speaker),14,gray);empty.setGravity(Gravity.CENTER);root.addView(empty,new LinearLayout.LayoutParams(-1,dp(48)));grid=new GridView(activity);grid.setNumColumns(2);grid.setHorizontalSpacing(dp(12));grid.setVerticalSpacing(dp(12));grid.setPadding(0,dp(14),0,dp(12));grid.setClipToPadding(false);grid.setSelector(android.R.color.transparent);root.addView(grid,new LinearLayout.LayoutParams(-1,0,1));grid.setEmptyView(empty);
        adapter=new BaseAdapter(){public int getCount(){return filtered.size();}public Object getItem(int position){return filtered.get(position);}public long getItemId(int position){return filtered.get(position);}public View getView(int position,View recycled,ViewGroup parent){int speaker=filtered.get(position);boolean chosen=speaker==host.selected(),playing=host.previewing(speaker);LinearLayout card=new LinearLayout(activity);card.setOrientation(1);card.setGravity(Gravity.CENTER_HORIZONTAL);card.setPadding(dp(12),dp(16),dp(12),dp(10));GradientDrawable fill=shape(chosen?0xfffff1ef:0xfff6f7f9,16);if(chosen)fill.setStroke(dp(1),0xffe98e83);card.setBackground(fill);card.setSelected(chosen);card.setOnClickListener(v->{host.select(speaker);refresh();});TextView avatar=text(String.format(AppLanguage.locale(activity),"%02d",speaker+1),24,chosen?red:0xff707986);avatar.setGravity(Gravity.CENTER);avatar.setTypeface(null,Typeface.BOLD);avatar.setBackground(shape(chosen?0xffffdfd9:0xffe8ebef,30));card.addView(avatar,new LinearLayout.LayoutParams(dp(56),dp(56)));TextView name=text((pack.speakerName(speaker).isEmpty()?activity.getString(R.string.vp_voice_number,speaker+1):pack.speakerName(speaker))+(chosen?"  ✓":""),14,chosen?red:ink);name.setGravity(Gravity.CENTER);name.setPadding(0,dp(10),0,dp(5));card.addView(name,new LinearLayout.LayoutParams(-1,-2));TextView preview=text(playing?"Ⅱ  "+activity.getString(R.string.ui_214):"▶  "+activity.getString(R.string.ui_211),12,red);preview.setGravity(Gravity.CENTER);preview.setBackground(shape(playing?0xffffdbd4:Color.WHITE,22));card.addView(preview,new LinearLayout.LayoutParams(-1,dp(44)));preview.setOnClickListener(v->{host.preview(speaker);refresh();});card.setContentDescription(name.getText());return card;}};
        grid.setAdapter(adapter);search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void onTextChanged(CharSequence s,int start,int before,int count){filter(s.toString());}public void afterTextChanged(Editable s){}});filter("");grid.post(()->grid.setSelection(Math.max(0,host.selected())));
        Window w=getWindow();if(w!=null){w.setBackgroundDrawableResource(android.R.color.transparent);w.setGravity(Gravity.BOTTOM);w.addFlags(WindowManager.LayoutParams.FLAG_DIM_BEHIND);w.setDimAmount(.38f);w.setNavigationBarColor(Color.WHITE);w.setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE|WindowManager.LayoutParams.SOFT_INPUT_STATE_ALWAYS_HIDDEN);}
    }
    void filter(String query){filtered.clear();String normalized=query.trim().toLowerCase(Locale.ROOT);for(int i=0;i<pack.speakers;i++)if(normalized.isEmpty()||String.valueOf(i+1).contains(normalized)||pack.speakerName(i).toLowerCase(Locale.ROOT).contains(normalized)||activity.getString(R.string.vp_voice_number,i+1).toLowerCase(Locale.ROOT).contains(normalized))filtered.add(i);refresh();}
    void refresh(){if(adapter!=null)adapter.notifyDataSetChanged();}
    @Override public void show(){super.show();Window w=getWindow();if(w!=null)w.setLayout(-1,Math.round(activity.getResources().getDisplayMetrics().heightPixels*.84f));}
    @Override public void dismiss(){host.stop();super.dismiss();}
}
